const positiveRankByWorld=[0,1,2,3,1,0,3,2,0,1,2,3];
for(const [index,w] of fileWorlds.entries()){
 const sorted=[...w.records].sort((a,b)=>a.id.localeCompare(b.id,'en'));
 const positive=sorted.find(r=>r.support.every(Boolean));
 const ordered=[];ordered[positiveRankByWorld[index]]=positive;
 for(const r of sorted)if(r!==positive){let at=0;while(ordered[at])at++;ordered[at]=r;}
 w.records=ordered.map((r,at)=>{const nextId=`${r.id.slice(0,-1)}${String.fromCharCode(65+at)}`;return {...r,id:nextId,text:r.text.replaceAll(r.id,nextId)};});
 w.positive_lexical_position=positiveRankByWorld[index]+1;
}

