 const folderFiles={'task.json':JSON.stringify(task),'selection.json':'[]'};for(const r of w.records)folderFiles[`record-${r.id}.md`]=`${r.id}: ${r.text}`;
 const expected=w.records.filter(r=>r.support.every(Boolean)).map(r=>r.id).sort();const expectedFiles={...folderFiles,'selection.json':JSON.stringify(expected)};const group=`v14:${w.slug}:world`;
 const children=w.records.map(r=>({match:`record-${r.id}.md`,calls:[['read_file',{path:`record-${r.id}.md`}],['return_result',{status:'success',value:r.support.every(Boolean)}]]}));
