function validate(){
 if(fileWorlds.length!==12||iterateWorlds.length!==12)throw Error('V14 must contain 12 new file worlds and 12 new iterate worlds');
 for(const w of fileWorlds){if(w.records.length!==4||w.clauses.length!==4)throw Error(`${w.slug}: expected four records and clauses`);for(const r of w.records){const failures=r.support.map((yes,i)=>yes?null:i).filter(i=>i!==null);if(r.support.length!==4||r.support.some(v=>typeof v!=='boolean')||failures.length>1)throw Error(`${w.slug}/${r.id}: inconsistent clause support`);if(failures.length!==0&&failures.length!==1)throw Error(`${w.slug}/${r.id}: negative must fail exactly one clause`);}if(w.records.filter(r=>r.support.every(Boolean)).length!==1)throw Error(`${w.slug}: exactly one positive required`);}
 for(const w of iterateWorlds){const fs=Object.keys(w.fields),seen=w.fieldByPass.flat();if(w.passes.length!==3||fs.length!==4||new Set(seen).size!==4||seen.some(f=>!fs.includes(f)))throw Error(`${w.slug}: expected three ordered passes over four string fields`);if(fs.some(f=>typeof w.expected[f]!=='string'||typeof w.initial[f]!=='string'||w.initial[f]===w.expected[f]))throw Error(`${w.slug}: malformed initial/final string state`);for(const value of Object.values(w.expected))if(!w.packet.toLowerCase().includes(value.toLowerCase()))throw Error(`${w.slug}: expected value absent from packet: ${value}`);for(let i=0;i<3;i++){const prior=intermediate(w,i-1),next=intermediate(w,i);if(w.fieldByPass[i].some(f=>prior[f]===next[f]))throw Error(`${w.slug}: empty local pass`);for(const f of fs)if(!w.fieldByPass[i].includes(f)&&prior[f]!==next[f])throw Error(`${w.slug}: pass ${i} mutates carried field ${f}`);}}
}
validate();
const cases=[...fileWorlds.map(fileCase),...iterateWorlds.map(iterCase)];
if(cases.length!==24||cases.filter(x=>x.split==='train').length!==12||cases.filter(x=>x.split==='test').length!==12)throw Error('V14 split/case balance failure');
const groups=cases.flatMap(x=>x.source_groups);if(new Set(groups).size!==24)throw Error('V14 source groups are not unique');
