const positionCountsBySplit=Object.fromEntries(['train','test'].map(split=>[split,Object.fromEntries([1,2,3,4].map(rank=>[rank,fileWorlds.filter((w,i)=>i%2===(split==='train'?0:1)&&w.positive_lexical_position===rank).length]))]));
